    public void morph_options(Control owner)
    {
        var selected=selected_key(owner);if(selected.Count==0||selected["component"].AsGodotObject().Get("locked").AsBool())return;var component=selected["component"].As<Resource>();var frame=selected["key"].As<Resource>();string componentId=component.Get("id").AsString(),keyId=frame.Get("id").AsString();Resource? Lookup(){var item=Document(owner).Call("component",componentId).As<Resource>();return item?.Call("key_for_id",keyId).As<Resource>();}var popup=new PopupPanel {Name="MorphOptions"};style_popup(popup);owner.AddChild(popup);var outer=Attach(popup,new VBoxContainer());var scroll=Attach(outer,new ScrollContainer {CustomMinimumSize=new Vector2(480,260),HorizontalScrollMode=ScrollContainer.ScrollMode.Disabled});var panel=Attach(scroll,new VBoxContainer {SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});Caption(panel,"MORPH SETTINGS · outgoing transition");var keys=component.Call("sorted_keys").AsGodotArray();int index=keys.IndexOf(frame);if(index+1<keys.Count){var next=keys[index+1].As<Resource>();string nextId=next.Get("id").AsString();NumberControl(owner,panel,"Transition duration (s)",next.Get("time").AsDouble()-frame.Get("time").AsDouble(),.001,Document(owner).Get("duration").AsDouble(),.01,value=>{var item=Document(owner).Call("component",componentId).As<Resource>();var current=Lookup();if(current!=null&&item!=null)item.Call("key_for_id",nextId).AsGodotObject().Set("time",current.Get("time").AsDouble()+value);});}Caption(panel,"GROWTH / REVEAL OPTIONS");Choice(panel,new[]{"Point","Path","Directional","Shape expansion"},frame.Get("reveal_mode").AsString(),value=>ChangeKeys(owner,"Growth method",(item,key)=>{key.Set("reveal_mode",value);if(key.Get("mode").AsString()=="Reveal")key.Set("mode","Grow / Reveal");}));var origin=Attach(panel,new CheckButton {Text="Custom morph origin (otherwise use state pivot)",ButtonPressed=frame.Get("origin_enabled").AsBool()});origin.Toggled+=value=>ChangeKeys(owner,"Morph origin",(item,key)=>key.Set("origin_enabled",value));var row=Attach(panel,new HBoxContainer());for(int axis=0;axis<2;axis++){int componentIndex=axis;NumberControl(owner,row,"Origin "+new[]{"X","Y"}[axis],frame.Get("morph_origin").AsVector2()[axis],0,1,.01,value=>{var current=Lookup();if(current!=null){var point=current.Get("morph_origin").AsVector2();point[componentIndex]=(float)value;current.Set("morph_origin",point);}});}NumberControl(owner,row,"Direction °",frame.Get("direction").AsDouble(),-360,360,1,value=>Lookup()?.Set("direction",value));var advanced=new VBoxContainer();var toggle=Attach(panel,new CheckButton {Text="Advanced correspondence and appearance"});panel.AddChild(advanced);advanced.Hide();toggle.Toggled+=value=>{advanced.Visible=value;scroll.CustomMinimumSize=new Vector2(scroll.CustomMinimumSize.X,value?Math.Min(480,owner.GetViewportRect().Size.Y-140):260);popup.CallDeferred("popup_centered",new Vector2I(500,(int)scroll.CustomMinimumSize.Y+52));};Choice(advanced,new[]{"Bounds","Local"},frame.Get("alignment").AsString(),value=>ChangeKeys(owner,"Correspondence alignment",(item,key)=>key.Set("alignment",value))).TooltipText="Bounds normalizes shape comparisons; Local emphasizes original positions. Neither crops or moves the component pivot.";Choice(advanced,new[]{"Feature reveal","Aligned blend"},frame.Get("appearance").AsString(),value=>ChangeKeys(owner,"Appearance transition",(item,key)=>key.Set("appearance",value)));Choice(advanced,new[]{"Fast","High"},frame.Get("quality").AsString(),value=>ChangeKeys(owner,"Morph quality",(item,key)=>key.Set("quality",value)));NumberControl(owner,advanced,"Interior feature preservation",frame.Get("preservation").AsDouble(),0,1,.01,value=>Lookup()?.Set("preservation",value));NumberControl(owner,advanced,"Topology expansion bias",frame.Get("topology_bias").AsDouble(),-.15,.15,.005,value=>Lookup()?.Set("topology_bias",value));Action(outer,"Done",()=>popup.Hide());popup.PopupHide+=()=>popup.QueueFree();popup.PopupCentered(new Vector2I(500,312));
    }
    public void match_dialog(Control owner)
    {
        var selected=selected_key(owner);if(selected.Count==0||selected["component"].AsGodotObject().Get("locked").AsBool())return;var item=selected["component"].As<Resource>();var key=selected["key"].As<Resource>();var keys=item.Call("sorted_keys").AsGodotArray();int index=keys.IndexOf(key);if(index+1>=keys.Count){Status(owner,"Add another state key to the right before matching a transition.");return;}var popup=GD.Load<GDScript>("res://Workspaces/TransformationWorkspace/transformation_match_editor.gd").New().As<PopupPanel>();popup.Set("workspace",owner);popup.Set("component_id",item.Get("id"));popup.Set("key_id",key.Get("id"));popup.Set("next_state_id",keys[index+1].AsGodotObject().Get("state_id"));owner.AddChild(popup);popup.Call("open");
    }
}
